struct PackingItem { let id: Int; let title: String }
func titleAt(_ values: [PackingItem], index: Int) -> String {
    guard values.indices.contains(index) else { return "Нет вещи" }
    return values[index].title
}
import XCTest
final class PackingTitleTests: XCTestCase {
    func testKnownIndex() {
        let values = [PackingItem(id: 91, title: "Куртка")]
        XCTAssertEqual(titleAt(values, index: 0), "Куртка")
    }
    func testInvalidIndexes() {
        let values = [PackingItem(id: 91, title: "Куртка")]
        XCTAssertEqual(titleAt(values, index: -1), "Нет вещи")
        XCTAssertEqual(titleAt(values, index: 1), "Нет вещи")
        XCTAssertEqual(titleAt([], index: 0), "Нет вещи")
    }
}

indices.contains проверяет обе границы. Отдельные утверждения ловят отрицательный индекс, верхнюю границу и пустой вход.

