struct PackingItem { let id: Int; let title: String }
final class PackingList {
    var values: [PackingItem] = []
    var selectedID: Int?
    func removeSelected() {
        guard let id = selectedID else { return }
        values.removeAll { $0.id == id }
        selectedID = nil
    }
}
let list = PackingList()
list.selectedID = 93
list.values = [PackingItem(id: 91, title: "Куртка")]
list.removeSelected()
assert(list.values.map { $0.id } == [91])
assert(list.selectedID == nil)
list.selectedID = 91
list.removeSelected()
assert(list.values.isEmpty)

Первый кадр приложения показывает remove(at:), а причина — устаревшая позиция после обновления. Удаление по id сохраняет контракт на исчезнувшей вещи; для настоящего отчёта нужны символы именно этой сборки.

final class PackingBadge {
    private(set) var text = "0 вещей"
    func update(count: Int) {
        text = "\(count) вещей"
    }
}
import XCTest
final class PackingBadgeTests: XCTestCase {
    func testBecomesEmpty() {
        let badge = PackingBadge()
        badge.update(count: 2)
        XCTAssertEqual(badge.text, "2 вещей")
        badge.update(count: 0)
        XCTAssertEqual(badge.text, "0 вещей")
    }
}

